void dl_do_relock(void)
{    
    timeout_q_remove((Timeout_Q_Func)dl_relock_timeout);
    
    dl.relock_window = TRUE;
    
    timeout_q_loop((Timeout_Q_Func)dl_relock_timeout,NULL,DL_RELOCK_TIMEOUT,1);
}

void dl_do_relock_reset(void)
{
    timeout_q_remove((Timeout_Q_Func)dl_relock_timeout);
    
    dl.relock_window = FALSE;
        
    TRACE("DL_DO_RELOCK_RESET\n\r");    
}

Timeout_Q_Status dl_relock_timeout(void)
{
	dl.relock_window = FALSE;
	
	TRACE("DL_DO_RELOCK2\n\r");
                
        if(dl.lock_status && !get_ign_status() && !dl.tr_status)
        {
            cmd_q_insert(INPUT_LOCK1|INPUT_ON,DL_CMD_INSERT_TIMEOUT); /*relock the car*/
        }
    
    return TIMEOUT_Q_COMPLETE;
}

